+      );
+    }
+
+    // Email the student their tracking number
+    const delivered = await sendQueryRaisedEmail(
+      record.student_email,
+      record.student_name || 'Student',
+      trackingId,
+      resolvedClassName,
+      queryType,
+      record.message,
+    );
+    // Notify the administration inbox
